#include <iostream>
#include <cstdio>
#include <cstring>
#include <queue>
#include <vector>
#include <cassert>
#include <cmath>
#include <string>
#include <algorithm>

using namespace std;

typedef long long ll;
typedef unsigned long long ull;
typedef long double ld;

const double EPS = 1e-9;
const double PI = acos(-1.0);
const int MOD = 1000000007;
const int INF = 2000000000;
const int MAX_SIZE = 210;
const int MAX_EDGES = 2 * MAX_SIZE * MAX_SIZE;
const int dx[4] = {1, 0, 0, -1};
const int dy[4] = {0, 1, -1, 0};
const int SOURCE = MAX_SIZE - 2;
const int SINK = MAX_SIZE - 1;

inline int square(int n) {
    return n * n;
}

struct FlowNetwork {
    int to[MAX_EDGES];
    int flow[MAX_EDGES], capacity[MAX_EDGES];
    int edgeCount;

    vector <int> adj[MAX_SIZE];
    bool visited[MAX_SIZE];

    FlowNetwork() : edgeCount(0) { }

    void connect(int u, int v, int cap) {
        to[edgeCount] = v;
        flow[edgeCount] = 0;
        capacity[edgeCount] = cap;
        adj[u].push_back(edgeCount++);

        to[edgeCount] = u;
        flow[edgeCount] = 0;
        capacity[edgeCount] = 0;
        adj[v].push_back(edgeCount++);
    }

    bool augment(int node, int target, int amount) {
        if (node == target) {
            return true;
        }

        visited[node] = true;

        for (int idx : adj[node]) {
            if (!visited[to[idx]] && capacity[idx] - flow[idx] >= amount &&
                augment(to[idx], target, amount)) {

                flow[idx] += amount;
                flow[idx ^ 1] -= amount;

                return true;
            }
        }

        return false;
    }

    int computeMaxFlow(int source, int sink) {
        int amount = 1 << 30;
        int total = 0;

        while (amount > 0) {
            if (augment(source, sink, amount)) {
                total += amount;
            } else {
                amount >>= 1;
            }

            memset(visited, false, sizeof visited);
        }

        return total;
    }
};

FlowNetwork network;

int gridSize, maxSteps;
char initial[15][15];
char target[15][15];
int dist[15][15];
bool seen[15][15];

bool inBounds(int x, int y) {
    return 0 <= x && x < gridSize &&
           0 <= y && y < gridSize &&
           initial[x][y] != 'Y' &&
           initial[x][y] != 'Z';
}

void computeDistances(int startX, int startY) {
    for (int i = 0; i < gridSize; i++) {
        for (int j = 0; j < gridSize; j++) {
            dist[i][j] = INF;
        }
    }

    queue <int> qx, qy;
    dist[startX][startY] = 0;
    qx.push(startX);
    qy.push(startY);

    while (!qx.empty()) {
        assert(!qy.empty());

        int cx = qx.front();
        int cy = qy.front();

        qx.pop();
        qy.pop();

        for (int k = 0; k < 4; k++) {
            int nx = cx + dx[k];
            int ny = cy + dy[k];

            if (inBounds(nx, ny) && dist[nx][ny] == INF) {
                dist[nx][ny] = dist[cx][cy] + 1;
                qx.push(nx);
                qy.push(ny);
            }
        }
    }
}

void explore(int startX, int startY) {
    queue <int> qx, qy, qlevel;
    memset(seen, false, sizeof seen);

    seen[startX][startY] = true;
    qx.push(startX);
    qy.push(startY);
    qlevel.push(0);

    while (!qx.empty()) {
        assert(!qy.empty());

        int cx = qx.front();
        int cy = qy.front();
        int level = qlevel.front();

        qx.pop();
        qy.pop();
        qlevel.pop();

        if (isdigit(target[cx][cy]) && target[cx][cy] != '0') {
            network.connect(startX * gridSize + startY, square(gridSize) + 1 + cx * gridSize + cy, INF);
        }

        if (level >= maxSteps) {
            continue;
        }

        for (int k = 0; k < 4; k++) {
            int nx = cx + dx[k];
            int ny = cy + dy[k];

            if (inBounds(nx, ny) && !seen[nx][ny]) {
                if (dist[nx][ny] > level + 1) {
                    qx.push(nx);
                    qy.push(ny);
                    qlevel.push(level + 1);
                } else if (dist[nx][ny] > level && isdigit(target[nx][ny]) && target[nx][ny] != '0') {
                    network.connect(startX * gridSize + startY, square(gridSize) + 1 + nx * gridSize + ny, INF);
                }

                seen[nx][ny] = true;
            }
        }
    }
}

void constructGraph() {
    int startX = -1, startY = -1;
    for (int i = 0; i < gridSize && startX == -1; i++) {
        for (int j = 0; j < gridSize && startX == -1; j++) {
            if (initial[i][j] == 'Z') {
                startX = i, startY = j;
            }
        }
    }

    computeDistances(startX, startY);

    for (int i = 0; i < gridSize; i++) {
        for (int j = 0; j < gridSize; j++) {
            if (isdigit(initial[i][j]) && initial[i][j] != '0') {
                network.connect(SOURCE, i * gridSize + j, initial[i][j] - '0');
            }
        }
    }

    for (int i = 0; i < gridSize; i++) {
        for (int j = 0; j < gridSize; j++) {
            if (isdigit(target[i][j]) && target[i][j] != '0') {
                network.connect(i * gridSize + j + square(gridSize) + 1, SINK, target[i][j] - '0');
            }
        }
    }

    for (int i = 0; i < gridSize; i++) {
        for (int j = 0; j < gridSize; j++) {
            if (isdigit(initial[i][j]) && initial[i][j] != '0') {
                explore(i, j);
            }
        }
    }
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("in", "r", stdin);
#endif

    scanf("%d %d", &gridSize, &maxSteps);

    scanf("\n");
    for (int i = 0; i < gridSize; i++) {
        gets(initial[i]);
    }

    scanf("\n");
    for (int i = 0; i < gridSize; i++) {
        gets(target[i]);
    }

    constructGraph();

    printf("%d\n", network.computeMaxFlow(SOURCE, SINK));

    return 0;
}
